import{_ as e,o as r,c as t,a6 as o}from"./chunks/framework.DNkVJs23.js";const u=JSON.parse('{"title":"Вопросы и ответы","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://eurekaffeine.github.io/sapphire-star-codex/ru/faq/"}],["meta",{"property":"og:url","content":"https://eurekaffeine.github.io/sapphire-star-codex/ru/faq/"}],["meta",{"property":"og:title","content":"Вопросы и ответы | Sapphire Star Codex"}],["meta",{"property":"og:description","content":"Данные Monster Hunter и подбор брони для Wilds, Rise с Sunbreak и World с Iceborne."}]]},"headers":[],"relativePath":"ru/faq/index.md","filePath":"ru/faq/index.md"}'),i={name:"ru/faq/index.md"};function n(l,a,s,h,p,d){return r(),t("div",null,[...a[0]||(a[0]=[o('<h1 id="вопросы-и-ответы" tabindex="-1">Вопросы и ответы <a class="header-anchor" href="#вопросы-и-ответы" aria-label="Permalink to &quot;Вопросы и ответы&quot;">​</a></h1><h2 id="какие-игры-поддерживаются" tabindex="-1">Какие игры поддерживаются? <a class="header-anchor" href="#какие-игры-поддерживаются" aria-label="Permalink to &quot;Какие игры поддерживаются?&quot;">​</a></h2><p>Поддерживаются Wilds, Rise с Sunbreak и World с Iceborne. Данные и механики каждой игры хранятся отдельно; игру можно выбрать на главном экране.</p><h2 id="где-скачать-приложение" tabindex="-1">Где скачать приложение? <a class="header-anchor" href="#где-скачать-приложение" aria-label="Permalink to &quot;Где скачать приложение?&quot;">​</a></h2><p>Версия Android доступна в <a href="https://play.google.com/store/apps/details?id=com.eurekaffeine.mhd" target="_blank" rel="noreferrer">Google Play</a>, HarmonyOS — в <a href="https://appgallery.huawei.com/app/detail?id=com.eurekaffeine.monsterhunterdex&amp;channelId=SHARE&amp;source=appshare" target="_blank" rel="noreferrer">AppGallery</a>. Версия iOS готовится к выпуску. Ссылки находятся в разделе <a href="./../#download">загрузки</a>; доступность зависит от региона и устройства.</p><h2 id="работает-ли-оно-без-интернета" tabindex="-1">Работает ли оно без интернета? <a class="header-anchor" href="#работает-ли-оно-без-интернета" aria-label="Permalink to &quot;Работает ли оно без интернета?&quot;">​</a></h2><p>Данные входят в состав приложения. Просмотр, поиск, избранное и подбор брони выполняются на устройстве. Для внешних сайтов и обновлений нужен интернет.</p><h2 id="как-работает-подбор-брони" tabindex="-1">Как работает подбор брони? <a class="header-anchor" href="#как-работает-подбор-брони" aria-label="Permalink to &quot;Как работает подбор брони?&quot;">​</a></h2><p>Задайте навыки и уровни, закрепите или исключите снаряжение и укажите количество имеющихся украшений. Rise также поддерживает собственные талисманы и усиленную броню. Результат зависит от данных и условий; расчёта урона здесь нет.</p><h2 id="какие-языки-доступны" tabindex="-1">Какие языки доступны? <a class="header-anchor" href="#какие-языки-доступны" aria-label="Permalink to &quot;Какие языки доступны?&quot;">​</a></h2><p>В приложении доступны 14 языков. Некоторые игровые тексты могут оставаться на английском. Если нет текста на латиноамериканском испанском, используется испанский из Испании, а затем английский.</p><p>English · 日本語 · 简体中文 · 繁體中文 · Français · Deutsch · Italiano · 한국어 · Español (España) · Español (Latinoamérica) · Português (Brasil) · Polski · Русский · العربية</p><h2 id="это-официальное-приложение" tabindex="-1">Это официальное приложение? <a class="header-anchor" href="#это-официальное-приложение" aria-label="Permalink to &quot;Это официальное приложение?&quot;">​</a></h2><p>Нет. Это независимое приложение поклонников, не связанное с CAPCOM и не одобренное ею. Изображения и данные Monster Hunter принадлежат CAPCOM Co., Ltd.</p>',14)])])}const f=e(i,[["render",n]]);export{u as __pageData,f as default};
